                        />
                    </div>
                    <button
                        onClick={() => handleOpenSheet()}
                        className="flex items-center gap-2 bg-indigo-600 hover:bg-indigo-700 text-white px-4 py-2 rounded-lg text-sm font-bold transition-all shadow-sm"
                    >
                        <Plus size={18} /> ┘à┘ê╪▒╪» ╪¼╪»┘è╪»
                    </button>
                </div>
            </div>

            {/* TABLE */}
            <div className="bg-white border border-gray-200 rounded-xl overflow-hidden shadow-sm flex-1 flex flex-col">
                <div className="overflow-x-auto">
                    <table className="w-full text-right text-sm">
                        <thead className="bg-gray-50 border-b border-gray-200 text-gray-600">
                            <tr>
                                <th className="px-5 py-4 font-semibold w-12"></th>
                                <th className="px-5 py-4 font-semibold">╪º╪│┘à ╪º┘ä┘à┘ê╪▒╪»</th>
                                <th className="px-5 py-4 font-semibold">╪¬┘ê╪º╪╡┘ä</th>
                                <th className="px-5 py-4 font-semibold">╪º┘ä┘à┘å╪¬╪¼╪º╪¬ ╪¬┘ê╪▒┘è╪»</th>
                                <th className="px-5 py-4 font-semibold">╪º┘ä┘à╪¿┘ä╪║ ╪º┘ä┘à╪│╪¬╪¡┘é ┘ä┘ç (╪»╪¼)</th>
                                <th className="px-5 py-4 font-semibold text-center">╪Ñ╪¼╪▒╪º╪í╪º╪¬</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-gray-200">
                            {loading ? (
                                <tr><td colSpan={6} className="text-center py-12 text-gray-500 font-medium">╪¼╪º╪▒┘è ╪º┘ä╪¬╪¡┘à┘è┘ä...</td></tr>
                            ) : filteredSuppliers.length === 0 ? (
                                <tr><td colSpan={6} className="text-center py-12 text-gray-500 font-medium">┘ä╪º ┘è┘ê╪¼╪» ┘à┘ê╪▒╪»┘è┘å</td></tr>
                            ) : (
                                filteredSuppliers.map((s) => {
                                    const isExpanded = expandedRows.includes(s.id);
                                    return (
                                        <React.Fragment key={s.id}>
