                                                            {!s.products ? (
                                                                <div className="text-gray-500 text-sm">╪¼╪º╪▒┘è ╪º┘ä╪¬╪¡┘à┘è┘ä...</div>
                                                            ) : s.products.length === 0 ? (
                                                                <div className="text-gray-500 text-sm">┘ä╪º ╪¬┘ê╪¼╪» ┘à┘å╪¬╪¼╪º╪¬ ┘à╪▒╪¬╪¿╪╖╪⌐ ╪¿┘ç╪░╪º ╪º┘ä┘à┘ê╪▒╪»</div>
                                                            ) : (
                                                                <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-3">
                                                                    {s.products.map(p => (
                                                                        <div key={p.id} className="bg-white border border-gray-200 p-3 rounded-lg flex flex-col gap-1 shadow-sm">
                                                                            <span className="font-bold text-gray-900 text-sm">{p.name}</span>
